// --- 1. Obtener datos de entrada ---
const fasesRequeridas = $('Configuración de Fases').first().json.fases_requeridas;
const campañasActivas = $('Aggregate').first().json.campañas;

const nombresDeCampañas = campañasActivas.map(c => c.name.toUpperCase());
const fasesFaltantes = [];

// --- 2. Lógica de Verificación ---
for (const fase of fasesRequeridas) {
  const regex = new RegExp(fase.regex, 'i');
  const faseEncontrada = nombresDeCampañas.some(nombre => regex.test(nombre));

  if (!faseEncontrada) {
    fasesFaltantes.push(fase.nombre);
  }
}

// --- 3. Salida Booleana para Tratamiento ---
// Determinamos si requiere tratamiento (si hay faltantes)
const requiereTratamiento = fasesFaltantes.length > 0;

return [{
  json: {
    // Si es true, el nodo IF posterior dejará pasar el flujo.
    // Si es false, el flujo se detiene o va por la rama 'false'.
    action: requiereTratamiento, 

    // Datos útiles para el tratamiento (si action es true)
    fases_faltantes: fasesFaltantes,
    campañas_activas_nombres: nombresDeCampañas.map(nombre => `• ${nombre}`).join('\n')
  }
}];

// --- 1. Acceso a los datos de entrada ---
// Datos del cliente
const clientData = $('data-entry').first().json;
// Datos de la verificación de fases (nuestro nuevo nodo)
const analisisFases = $input.first().json;

// --- 2. Extracción de Datos ---
const { nombre: clienteNombre, empresa: clienteEmpresa, "ID-cuenta-publicitaria": idCuentaPublicitaria } = clientData;
const { fases_faltantes, campañas_activas_nombres } = analisisFases;

// --- 3. Construcción del Texto de Análisis ---
const estadoGeneral = "Reporte Existente";

// El título de la alerta es ahora más específico.
const tituloAnalisis = "AVISO: Faltan Fases de Campañas Activas";

// Se prepara la información del cliente.
const infoCliente = `*Cliente:* ${clienteNombre}\n*Empresa:* ${clienteEmpresa}\n*ID Cuenta Publicitaria:* ${idCuentaPublicitaria}`;

// Se prepara la lista de fases faltantes.
const listaFasesFaltantesTexto = `\n*Fases Faltantes:*\n${fases_faltantes.map(fase => `❌ ${fase}`).join('\n')}`;

// Se prepara la lista de campañas activas actuales para dar contexto.
const listaCampañasTexto = `\n*Campañas Activas Actualmente:*\n${campañas_activas_nombres}`;

// Se ensambla el texto final.
const textoFinal = `${tituloAnalisis}\n\n${infoCliente}\n${listaFasesFaltantesTexto}\n${listaCampañasTexto}`;

// --- 4. Objeto de Salida ---
return [{
    json: {
        estado_general: estadoGeneral,
        texto_final: textoFinal
    }
}];

